<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\TokenSecurity\Infrastructure\Driver\Rest;

use DateInterval;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Psr\SimpleCache\CacheInterface;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenSigner;
use OpenApi\Attributes as OA;

/**
 * REST controller that exposes the JSON Web Key Set (JWKS) endpoint for a tenant.
 *
 * The JWKS document contains all RSA public keys currently valid for the tenant,
 * allowing external OAuth resource servers and OIDC relying parties to verify
 * tokens without contacting this server on every request. To reduce latency and
 * database load, the serialized JWKS JSON is cached in the injected PSR-16 cache
 * for one hour. The response includes ETag and Cache-Control headers so that
 * downstream HTTP caches and clients can perform conditional GET requests. Clients
 * should poll this endpoint when they encounter an unknown kid in a JWT header.
 */
class JwksController
{
    private const string CACHE_KEY = 'jwks_public_keyset';

    public function __construct(private readonly TokenSigner $tokenHandler, private readonly CacheInterface $cacheInterface)
    {
    }

    #[OA\Get(
        path: '/oauth/openid/{tenant}/jwks',
        summary: 'JSON Web Key Set',
        description: 'Public keys for JWT signature verification. Cached for 1 hour.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(
                response: 200,
                description: 'JWKS',
                content: new OA\JsonContent(properties: [
                    new OA\Property(property: 'keys', type: 'array', items: new OA\Items(
                        properties: [
                            new OA\Property(property: 'kty', type: 'string', example: 'RSA'),
                            new OA\Property(property: 'use', type: 'string', example: 'sig'),
                            new OA\Property(property: 'kid', type: 'string'),
                            new OA\Property(property: 'alg', type: 'string', example: 'RS256'),
                            new OA\Property(property: 'n', type: 'string'),
                            new OA\Property(property: 'e', type: 'string'),
                        ]
                    )),
                ])
            ),
        ]
    )]
    /**
     * Returns the tenant's JWKS as a JSON response, serving from cache when available.
     * Attaches an ETag derived from the payload hash and a one-hour Cache-Control header.
     */
    public function get(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $key = self::CACHE_KEY;
        if (!$this->cacheInterface->has($key)) {
            $data = $this->tokenHandler->keysAsJwks($tenant);
            $encoded = json_encode($data);
            $txt = $encoded !== false ? $encoded : '{}';
            $this->cacheInterface->set($key, $txt, new DateInterval("PT1H"));
        } else {
            $txt = (string) $this->cacheInterface->get($key);
        }
        $etag = '"' . md5($txt) . '"';
        $response->getBody()->write($txt);
        return $response
                    ->withHeader('Etag', $etag)
                    ->withHeader('Cache-Control', 'public, max-age=3600, immutable')
                    ->withHeader('Content-Type', 'application/json');
    }
}
